'use strict';
function dropPercent(chance){return (chance*100).toLocaleString('en-US',{maximumFractionDigits:2})+'%'}
function renderStageDrops(level,boss=false){const group=document.createElement('span');group.className='stage-drops';group.setAttribute('aria-label','รายการดรอป Lv.'+level);const legend=document.createElement('span');legend.className='stage-drop-legend';legend.textContent=boss?'บอส · สุ่ม 1 กล่อง 100%':'ปกติ / Elite · สุ่ม 1 กล่อง 100%';group.append(legend);const cells=document.createElement('span');cells.className='stage-drop-items';const normal=monsterLootPreview(level,boss?'boss':'normal'),elite=monsterLootPreview(level,'elite');for(const d of normal){const cell=document.createElement('span');cell.className='stage-drop-cell';cell.dataset.kind=d.kind;cell.dataset.type=d.type||'money';cell.dataset.chance=d.chance;const other=elite.find(e=>e.kind===d.kind&&e.type===d.type),rate=d.kind==='money'||boss?dropPercent(d.chance):dropPercent(d.chance)+' / '+dropPercent(other.chance);let name,detail,badge;if(d.kind==='box'){const id=boxKey(d.type,d.level);cell.innerHTML=boxIcon(d.type);badge=d.type==='secondary'?'ขั้น '+skillBoxTier(id):String(d.level);name=boxName(id);detail=boxDescription(id)+' · เข้ากระเป๋าทันที'}else{cell.innerHTML='<svg class="stage-money-icon" viewBox="0 0 40 40" aria-hidden="true"><circle cx="20" cy="20" r="14" fill="#c5a55f" stroke="#f5dfa0" stroke-width="2"/><circle cx="20" cy="20" r="10" fill="none" stroke="#f1d590"/><path d="M20 10v20M15 14h8a4 4 0 0 1 0 8h-6a4 4 0 0 0 0 8h8" fill="none" stroke="#fff0b8" stroke-width="2"/></svg>';badge='×'+d.amount;name='เงิน '+d.amount.toLocaleString()+' เหรียญ';detail='Lv.มอนสเตอร์ × 10 · เข้ากระเป๋าทันที'}const label=document.createElement('span');label.className='stage-drop-level';label.textContent=badge;const chance=document.createElement('span');chance.className='stage-drop-chance';chance.textContent=rate;cell.append(label,chance);const description=detail+'\n'+(boss?'บอส '+rate:d.kind==='money'?'ทั่วไปและ Elite '+rate:'ทั่วไป '+dropPercent(d.chance)+' · Elite '+dropPercent(other.chance));cell.title=name+'\n'+description;cell.setAttribute('aria-label',name+' · '+(boss?'บอส ':d.kind==='money'?'':'ทั่วไป / Elite ')+rate);attachLootDetail(cell,{name,description});cells.append(cell)}group.append(cells);return group}
